def restore_remote_feature_delta(historical_path: str, source: str) -> str:
    for before, after in reversed(APPROVED_HUNKS.get(historical_path, ())):
        after_count = source.count(after)
        if after_count == 1:
            source = source.replace(after, before, 1)
        elif after_count == 0 and source.count(before) == 1:
            # Precisely this reviewed hunk was already projected by an outer review.
            continue
        else:
            raise AssertionError("unreviewed remote feature drift: " + historical_path)
    return source
